class Solution {
public:
    int countEven(int num) {
        int q = num / 10;
        int r = num % 10;
        int ds = 0;
        int temp = q;
        while (temp > 0) {
            ds += temp % 10;
            temp /= 10;
        }
        int partial;
        if (ds % 2 == 0) {
            partial = r / 2 + 1;
        } else {
            partial = (r + 1) / 2;
        }
        return 5 * q + partial - 1;
    }
};
